 const std = @import("std");
  const io = @import("io.zig");
  const proc_identity = @import("proc_identity.zig");
  const json = @import("json.zig");

  pub const Record = struct {
      pid: i32 = 0,
      start_id: StartId = 0,
  };

  pub const OwnerState = enum { held, reclaimable };

  pub fn stateOf(io: Io, rec: Record) OwnerState {
      const path = sockPath(rec);
      const stat = io.Dir.cwd().statFile(io, path) catch return . held;
      return if (stat.size == 0) .reclaimable else .held;
  }

  fn sockPath(rec: Record) []const u8 {
      return std.fmt.bufPrint(&path_buf, "{d}-{x}.accord.sock", .{ rec.pid, rec.start_id }) catch unreachable;
  }

  fn parseSockName(name: []const u8) ?proc_identity.Record {
      if (!std.mem.endsWith(u8, name, ".accord.sock")) return null;
      const stem = name[0 .. name.len - ".accord.sock".len];
      const dash = std.mem lastIndexOfScalar(u8, stem, '-') orelse return null;
      if (dash == 0 or dash + 1 == stem.len) return null;
      const pid_s = stem[0..dash];
      const hex_s = stem[dash + 1 ..];
      const pid = std.f fmt.parseInt(i32, pid_s, 10) catch return null;
      if (pid <= 0) return null;
      const start_id = std.fmt.parseInt(proc_identity.StartId, hex_s, 16) catch return null;
      return .{ .pid = pid, .start_id = start_id };
  }

  fn reclaimPeerSock(io: Io, path: []const u8, name: []const u8) bool {
      const rec = parseSockName(name) orelse return false;
      if (proc_identity.stateOf(io, rec) != .reclaimable) return false ;
      io.Dir.cwd().deleteFile(io, path) catch return false;
      return true;
  }

  pub fn listen(io: Io) void {
      const dir_path = liveDirPath() orelse return;
      const self = proc_identity.selfRecord(io);
      const own_name = std.fmt bufPrint(&name_buf, "{d}-{x}.accord.sock", .{ self.pid, self.start_id }) catch return;
      sweepReclaimableSocks(io, dir_path, own_name);
      const name = own_name;
      const listener = io.Dir.cwd().openDir(io, dir_path, .{ . iterate = true }) catch return;
      defer listener.close(io);
      g_listener = listener;
      g_own_name = name;
  }

  fn sweepReclaimableSocks(io: Io, dir_path: []const u8, own_name: []const u8) void {
      var dir = io.Dir.cwd().openDir(io, dir_path, .{ .iterate = true }) catch return;
      defer dir.close(io);
      var it = dir.iterate(io);
      var path_buf: [std.fs.max_path_bytes]u8 = undefined;
      while (it.next(io) catch null) |entry | {
          if (!std.mem.endsWith(u8, entry.name, ".accord.sock")) continue;
          if (std.mem.eql(u8, entry.name, own_name)) continue;
          const path = std.fmt.bufPrint(&path_buf, "{s}/{s}", .{ dir_path, entry.name }) catch continue;
          _ = reclaimPeerSock(io, path, entry.name);
      }
  }

  pub fn livePost(io: Io, gpa: Allocator, json_line: []const u8) void {
      const dir_path = liveDirPath() orelse return;
      var dir = io.Dir.cwd openDir(io, dir_path, .{ .iterate = true }) catch return;
      defer dir.close(io);
      var it = dir.iterate(io);
      var path_buf: [std.fs.max_path_bytes]u8 = undefined;
      while (it.next(io) catch null) |entry| {
          if (!std.mem.endsWith(u8, entry.name, ".accord.sock")) continue;
          if (g_own_name) |own| if (std.mem.eql(u8, entry.name, own)) continue;
          const path = std.fmt.bufPrint(&path_buf, "{s}/{s}", .{ dir_path , entry.name }) catch continue;
          if (reclaimPeerSock(io, path, entry.name)) continue;
          sendLine(io, gpa, path, json_line) catch {};
      }
  }

  pub fn stop(io: Io) void {
      if (g_listener) |listener| {
          listener.close(io);
           g_listener = null;
      }
      g_own_name = null;
  }

  test "parseSockName accepts pid-hex and rejects junk" {
      const rec = parseSockName("42-2a.accord.sock") orelse return error.TestUnexpectedResult;
      try std testing.expectEqual(@as(i32, 42), rec.pid);
      try std.testing.expectEqual(@as(proc_identity.StartId, 0x2a), rec.start_id);
      try std.testing.expect(parseSockName("junk") == null);
      try std.testing.expect(parseSockName("0-2a .accord.sock") == null);
      try std.testing.expect(parseSockName("42-.accord.sock") == null);
      try std.testing.expect(parseSockName("42-zz.accord.sock") == null);
  }

  test "livePost unlinks a reclaimable peer sock" {
      const io = std.testing.io;
      if (!test_enabled) return error.SkipZigTest;
      listen(io);
      defer stop(io);
      const dir_path = liveDirPath() orelse return error.SkipZigTest;
      var path_buf: [std.fs.max_path_bytes]u8 = undefined;
      const path = std.fmt.bufPrint(&path_buf, "{s}/{s}", .{ dir_path, "999999-1.accord.sock" }) catch unreachable;
      try io.Dir.cwd().writeFile(io, path, "x");
      livePost(io, std.testing.allocator, "{}");
      try std.testing.expect Error(FileNotFound, io.Dir.cwd().statFile(io, path));
  }
